using Microsoft.EntityFrameworkCore; using SimplexLawFirm.Data; using SimplexLawFirm.Models; using SimplexLawFirm.Services.Notifications;
namespace SimplexLawFirm.Services;
public interface IFeeDiscountService { Task<FeeDiscountRequest> RequestAsync(int invoiceId,int clientId,decimal proposed,string reason,CancellationToken ct=default); Task DecideAsync(int id,int directorId,FeeDiscountStatus status,decimal? counter,string reason,CancellationToken ct=default); }
public sealed class FeeDiscountService(ApplicationDbContext db, INotificationService notices) : IFeeDiscountService {
 public async Task<FeeDiscountRequest> RequestAsync(int invoiceId,int clientId,decimal proposed,string reason,CancellationToken ct=default){var invoice=await db.Invoices.Include(x=>x.Case).Include(x=>x.Payments).SingleOrDefaultAsync(x=>x.Id==invoiceId&&x.ClientId==clientId&&!x.IsPaid,ct)??throw new InvalidOperationException("Choose an unpaid invoice.");var outstanding=invoice.TotalAmount-invoice.Payments.Sum(x=>x.Amount);if(proposed<=0||proposed>=outstanding||string.IsNullOrWhiteSpace(reason))throw new InvalidOperationException("The proposed payment must be above zero, below the outstanding balance, and explained.");var matterType=invoice.Case?.CaseType??"General";var policy=await db.FeeDiscountPolicies.OrderByDescending(x=>x.MatterType==matterType).FirstOrDefaultAsync(x=>x.MatterType==matterType||x.MatterType=="General",ct)??new FeeDiscountPolicy();var paid=await db.Invoices.Where(x=>x.ClientId==clientId&&x.IsPaid).CountAsync(ct);var overdue=await db.Invoices.CountAsync(x=>x.ClientId==clientId&&!x.IsPaid&&x.DueDate<DateTime.UtcNow,ct);var reliable=paid>=1&&overdue<=1;var discount=(outstanding-proposed)/outstanding*100m;var threshold=outstanding*policy.MinimumRecoveryPercent/100m;var automatic=reliable&&proposed>=threshold&&discount<=policy.AutomaticApprovalPercent;var item=new FeeDiscountRequest{InvoiceId=invoiceId,ClientId=clientId,OriginalAmount=outstanding,ProposedAmount=proposed,DiscountPercent=discount,Reason=reason.Trim(),MinimumRecoveryPercentSnapshot=policy.MinimumRecoveryPercent,AutomaticApprovalPercentSnapshot=policy.AutomaticApprovalPercent,PaymentReliability=reliable?"Good":"Needs Director review",Recommendation=automatic?"Auto-approve: payment history and delegated limit meet policy.":"Escalate: payment history, recovery threshold, or approval limit requires Director review.",Status=automatic?FeeDiscountStatus.AutomaticallyApproved:FeeDiscountStatus.PendingDirector};db.Add(item);if(automatic){invoice.TotalAmount=proposed;invoice.Amount=Math.Min(invoice.Amount,proposed);invoice.Notes+=("\nDiscount approved: "+reason.Trim());item.DecidedAtUtc=DateTime.UtcNow;}else foreach(var director in await db.Users.Where(x=>(x.Role==UserRole.Director||x.Role==UserRole.Admin)&&x.IsActive).Select(x=>x.Id).ToListAsync(ct))await notices.QueueAsync(director,"FeeDiscount","Fee discount review required",item.Recommendation,$"/FeeDiscount/Details/{item.Id}",$"fee-discount-{item.Id}-{director}",ct);db.AuditEntries.Add(new(){ActorUserId=null,EntityType=nameof(FeeDiscountRequest),EntityId=item.Id.ToString(),Action="Fee discount request submitted"});await db.SaveChangesAsync(ct);return item;}
 public async Task DecideAsync(int id,int directorId,FeeDiscountStatus status,decimal? counter,string reason,CancellationToken ct=default){if(!await db.Users.AnyAsync(x=>x.Id==directorId&&(x.Role==UserRole.Director||x.Role==UserRole.Admin),ct))throw new UnauthorizedAccessException();var item=await db.FeeDiscountRequests.Include(x=>x.Invoice).SingleAsync(x=>x.Id==id&&x.Status==FeeDiscountStatus.PendingDirector,ct);if(string.IsNullOrWhiteSpace(reason)||(status==FeeDiscountStatus.CounterOffered&&(!counter.HasValue||counter<=0||counter>=item.OriginalAmount)))throw new InvalidOperationException("Record a reason and a valid counter-offer where applicable.");item.Status=status;item.CounterOfferAmount=counter;item.DecidedByUserId=directorId;item.DecisionReason=reason.Trim();item.DecidedAtUtc=DateTime.UtcNow;if(status==FeeDiscountStatus.Approved){item.Invoice.TotalAmount=item.ProposedAmount;item.Invoice.Amount=Math.Min(item.Invoice.Amount,item.ProposedAmount);}db.AuditEntries.Add(new(){ActorUserId=directorId,EntityType=nameof(FeeDiscountRequest),EntityId=id.ToString(),Action=$"Fee discount {status}"});await db.SaveChangesAsync(ct);}
}
